window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["cursor"]={html:"<div class=\"own-cursor\">\n  <!-- ── NAV ─────────────────────────────────────────────────────────────── -->\n  <header class=\"cu-nav\" id=\"cuNav\">\n    <a class=\"cu-wordmark\" href=\"#cu-top\" aria-label=\"Northwind home\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 3.5 20 12 4 20.5Z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linejoin=\"round\"/></svg>Northwind</a>\n    <nav class=\"cu-menu\" aria-label=\"Primary\">\n      <a href=\"#cu-pricing\">Pricing</a>\n      <a href=\"#cu-features\">Features</a>\n      <a href=\"#cu-timeline\">Enterprise</a>\n      <a href=\"#cu-blog\">Blog</a>\n      <a href=\"#cu-foot\">Careers</a>\n    </nav>\n    <div class=\"cu-nav-right\">\n      <a class=\"cu-nav-link\" href=\"#\">Sign in</a>\n      <a class=\"cu-btn cu-btn-ink\" href=\"#cu-pricing\">Download</a>\n      <button class=\"cu-burger\" type=\"button\" id=\"cuBurger\" aria-label=\"Open menu\" aria-expanded=\"false\"><span></span><span></span><span></span></button>\n    </div>\n  </header>\n\n  <main id=\"cu-top\">\n    <!-- ── HERO + IDE MOCKUP ──────────────────────────────────────────────── -->\n    <section class=\"cu-hero\" aria-labelledby=\"cuHeroH\">\n      <h1 id=\"cuHeroH\" class=\"cu-hero-title\">The operations editor<br>that thinks in your model</h1>\n      <p class=\"cu-hero-sub\">Northwind is where the analyst and the line lead meet — one warm, quiet surface for querying, editing, and reconciling the operation.</p>\n      <div class=\"cu-hero-cta\">\n        <a class=\"cu-btn cu-btn-ink cu-btn-lg\" href=\"#cu-pricing\">Download for macOS</a>\n        <a class=\"cu-link\" href=\"#cu-features\">See the features <span aria-hidden=\"true\">&rarr;</span></a>\n      </div>\n\n      <div class=\"cu-ide\" aria-label=\"Northwind editor mockup\">\n        <div class=\"cu-ide-bar\">\n          <span class=\"cu-ide-tab cu-ide-tab-on\">reconcile.ts</span>\n          <span class=\"cu-ide-tab\">week-41.json</span>\n          <span class=\"cu-ide-tab\">yield.sql</span>\n          <span class=\"cu-ide-spacer\"></span>\n          <span class=\"cu-ide-chip\">Ops model</span>\n        </div>\n        <div class=\"cu-ide-body\">\n          <div class=\"cu-ide-side\">\n            <span class=\"cu-ide-h\">Explorer</span>\n            <span class=\"cu-ide-file cu-ide-file-on\">reconcile.ts</span>\n            <span class=\"cu-ide-file\">yield.sql</span>\n            <span class=\"cu-ide-file\">week-41.json</span>\n            <span class=\"cu-ide-file\">digest.md</span>\n          </div>\n          <div class=\"cu-ide-main\">\n            <pre class=\"cu-ide-pre\"><code><span class=\"cu-ln\">1</span><span class=\"cu-k\">const</span> report = <span class=\"cu-k\">await</span> nw.<span class=\"cu-fn\">reconcile</span>({\n<span class=\"cu-ln\">2</span>  region: <span class=\"cu-s\">\"luzon\"</span>,\n<span class=\"cu-ln\">3</span>  week: <span class=\"cu-n\">41</span>,\n<span class=\"cu-ln\">4</span>});\n<span class=\"cu-ln\">5</span><span class=\"cu-c\">// 14 lines scanned &mdash; 3 flagged in Busan</span>\n<span class=\"cu-ln\">6</span>console.<span class=\"cu-fn\">log</span>(report.flagged);</code></pre>\n          </div>\n          <div class=\"cu-ide-chat\">\n            <span class=\"cu-ide-h\">Agent</span>\n            <div class=\"cu-ide-msg cu-ide-msg-user\">Reconcile week 41 across all regions.</div>\n            <div class=\"cu-ide-msg cu-ide-msg-ai\">Scanned 14 lines. Busan drifted 2.7% on lines 07 and 09. Drafting the shift digest now.</div>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── AI TIMELINE (signature pastel pills) ────────────────────────────── -->\n    <section id=\"cu-timeline\" class=\"cu-timeline\" aria-labelledby=\"cuTimelineH\">\n      <div class=\"cu-timeline-head\">\n        <h2 id=\"cuTimelineH\" class=\"cu-h2\">Watch the agent work</h2>\n        <p class=\"cu-lead\">Every step of a run, named and time-stamped &mdash; so you can trust the number it hands back.</p>\n      </div>\n      <ol class=\"cu-steps\" id=\"cuSteps\"></ol>\n    </section>\n\n    <!-- ── FEATURES (3-up hairline cards) ──────────────────────────────────── -->\n    <section id=\"cu-features\" class=\"cu-features\" aria-labelledby=\"cuFeaturesH\">\n      <div class=\"cu-features-head\">\n        <h2 id=\"cuFeaturesH\" class=\"cu-h2\">Built for the whole desk</h2>\n        <p class=\"cu-lead\">One editor, from the SQL the analyst writes to the digest the floor reads.</p>\n      </div>\n      <div class=\"cu-feature-grid\" id=\"cuFeatureGrid\"></div>\n    </section>\n\n    <!-- ── COMPARISON ──────────────────────────────────────────────────────── -->\n    <section class=\"cu-compare\" aria-labelledby=\"cuCompareH\">\n      <div class=\"cu-compare-card\">\n        <div class=\"cu-compare-col\">\n          <h3>Northwind</h3>\n          <ul>\n            <li>Governed ops model built in</li>\n            <li>Reconciliation with lineage</li>\n            <li>Agent runs are replayable</li>\n            <li>Digests the floor actually reads</li>\n          </ul>\n        </div>\n        <div class=\"cu-compare-col cu-compare-other\">\n          <h3 id=\"cuCompareH\">Spreadsheets + dashboards</h3>\n          <ul>\n            <li>Definitions drift per team</li>\n            <li>Totals that don't agree</li>\n            <li>No trace behind a number</li>\n            <li>Every shift rebuilds the board</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── CODE BLOCK ──────────────────────────────────────────────────────── -->\n    <section id=\"cu-blog\" class=\"cu-code-sec\" aria-labelledby=\"cuCodeH\">\n      <div class=\"cu-code-copy\">\n        <span class=\"cu-eyebrow\">Docs</span>\n        <h2 id=\"cuCodeH\" class=\"cu-h2\">One call to reconcile</h2>\n        <p class=\"cu-lead\">The ops model is a first-class citizen. Query it in SQL, or let the agent do it for you.</p>\n      </div>\n      <div class=\"cu-code-block\" role=\"group\" aria-label=\"SQL example\">\n        <div class=\"cu-code-bar\"><span>yield.sql</span><button class=\"cu-copy\" type=\"button\" id=\"cuCopy\">Copy</button></div>\n        <pre class=\"cu-pre\"><code id=\"cuCode\"><span class=\"cu-k\">select</span>\n  line_id,\n  <span class=\"cu-fn\">avg</span>(yield) <span class=\"cu-k\">as</span> yield_pct,\n  <span class=\"cu-fn\">count</span>(*) <span class=\"cu-k\">as</span> units\n<span class=\"cu-k\">from</span> ops.line_shift\n<span class=\"cu-k\">where</span> week = <span class=\"cu-n\">41</span>\n<span class=\"cu-k\">group by</span> line_id\n<span class=\"cu-k\">order by</span> yield_pct <span class=\"cu-k\">desc</span>;</code></pre>\n      </div>\n    </section>\n\n    <!-- ── PRICING ──────────────────────────────────────────────────────────── -->\n    <section id=\"cu-pricing\" class=\"cu-pricing\" aria-labelledby=\"cuPricingH\">\n      <div class=\"cu-pricing-head\">\n        <h2 id=\"cuPricingH\" class=\"cu-h2\">Pricing that reads like a magazine</h2>\n        <p class=\"cu-lead\">Start free. Add regions and seats when the operation grows.</p>\n      </div>\n      <div class=\"cu-tier-grid\">\n        <article class=\"cu-tier\">\n          <span class=\"cu-tier-name\">Hobby</span>\n          <span class=\"cu-tier-price\">Free</span>\n          <ul><li>1 region</li><li>1 seat</li><li>Community support</li></ul>\n          <a class=\"cu-btn cu-btn-secondary\" href=\"#\">Get started</a>\n        </article>\n        <article class=\"cu-tier cu-tier-featured\">\n          <span class=\"cu-tier-name\">Pro</span>\n          <span class=\"cu-tier-price\">$40<span>/seat/mo</span></span>\n          <ul><li>Unlimited regions</li><li>Agent timeline</li><li>Digests &amp; exports</li></ul>\n          <a class=\"cu-btn cu-btn-primary\" href=\"#\">Start free trial</a>\n        </article>\n        <article class=\"cu-tier\">\n          <span class=\"cu-tier-name\">Enterprise</span>\n          <span class=\"cu-tier-price\">Custom</span>\n          <ul><li>SSO &amp; audit</li><li>Private model</li><li>Dedicated support</li></ul>\n          <a class=\"cu-btn cu-btn-secondary\" href=\"#\">Contact sales</a>\n        </article>\n      </div>\n    </section>\n  </main>\n\n  <!-- ── CTA BAND ──────────────────────────────────────────────────────────── -->\n  <section class=\"cu-cta\" aria-labelledby=\"cuCtaH\">\n    <h2 id=\"cuCtaH\" class=\"cu-cta-title\">Try Northwind now</h2>\n    <a class=\"cu-btn cu-btn-primary cu-btn-lg\" href=\"#\">Download for macOS</a>\n  </section>\n\n  <!-- ── FOOTER ───────────────────────────────────────────────────────────── -->\n  <footer id=\"cu-foot\" class=\"cu-foot\">\n    <div class=\"cu-foot-cols\">\n      <div class=\"cu-foot-col\"><h3>Product</h3><a href=\"#\">Editor</a><a href=\"#\">Agent</a><a href=\"#\">Ops model</a><a href=\"#\">Pricing</a></div>\n      <div class=\"cu-foot-col\"><h3>Resources</h3><a href=\"#\">Docs</a><a href=\"#\">Blog</a><a href=\"#\">Forum</a><a href=\"#\">Changelog</a></div>\n      <div class=\"cu-foot-col\"><h3>Company</h3><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Security</a><a href=\"#\">Contact</a></div>\n      <div class=\"cu-foot-col\"><h3>Legal</h3><a href=\"#\">Privacy</a><a href=\"#\">Terms</a><a href=\"#\">DPA</a><a href=\"#\">Status</a></div>\n    </div>\n    <div class=\"cu-legal\">\n      <span>&copy; 2026 Northwind Analytics — a fictional product. Sample data, showcase only.</span>\n      <span class=\"cu-legal-right\">Made for the operations desk</span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — in Cursor's design language, for showcase.html ══════════════\n   Warm-cream editorial canvas (#f7f7f4) instead of dark IDE, warm near-black ink\n   (#26251e) at display weight 400 with negative tracking, a single Cursor Orange\n   voltage (#f54e00) used scarcely, JetBrains Mono on every code surface,\n   hairline-only depth (no shadows), and the AI-timeline pastel pills used only\n   inside in-product agent visualisations. 80px section rhythm. */\n\n.own-cursor {\n  --primary: #f54e00;\n  --primary-active: #d04200;\n  --ink: #26251e;\n  --body: #5a5852;\n  --muted: #807d72;\n  --muted-soft: #a09c92;\n  --hairline: #e6e5e0;\n  --hairline-soft: #efeee8;\n  --hairline-strong: #cfcdc4;\n  --canvas: #f7f7f4;\n  --canvas-soft: #fafaf7;\n  --surface-card: #ffffff;\n  --surface-strong: #e6e5e0;\n  --on-primary: #ffffff;\n  --timeline-thinking: #dfa88f;\n  --timeline-grep: #9fc9a2;\n  --timeline-read: #9fbbe0;\n  --timeline-edit: #c0a8dd;\n  --timeline-done: #c08532;\n  --semantic-error: #cf2d56;\n  --semantic-success: #1f8a65;\n\n  --font-display: 'CursorGothic', 'Inter', system-ui, 'Helvetica Neue', Helvetica, Arial, sans-serif;\n  --font-body: 'CursorGothic', 'Inter', system-ui, 'Helvetica Neue', Helvetica, Arial, sans-serif;\n  --font-mono: 'JetBrains Mono', 'Fira Code', monospace;\n\n  --r-xs: 4px;\n  --r-sm: 6px;\n  --r-md: 8px;\n  --r-lg: 12px;\n  --r-xl: 16px;\n  --r-pill: 9999px;\n\n  --gut: clamp(20px, 5cqi, 64px);\n  --section: clamp(56px, 7cqi, 80px);\n\n  position: relative;\n  border-radius: 13px;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--font-body);\n  font-size: 16px;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n  overflow-x: clip;\n}\n.own-cursor *, .own-cursor *::before, .own-cursor *::after { box-sizing: border-box; }\n.own-cursor a { color: inherit; text-decoration: none; }\n.own-cursor button { font: inherit; cursor: pointer; }\n.own-cursor :focus-visible { outline: 3px solid var(--primary); outline-offset: 2px; border-radius: 6px; }\n\n/* ── nav ───────────────────────────────────────────────────────────────────── */\n.own-cursor .cu-nav { position: sticky; top: 68px; z-index: 40; display: flex; align-items: center; gap: 24px; height: 64px; padding: 0 var(--gut); background: rgba(247, 247, 244, .88); border-bottom: 1px solid var(--hairline); backdrop-filter: saturate(180%) blur(12px); -webkit-backdrop-filter: saturate(180%) blur(12px); }\n.own-cursor .cu-wordmark { display: inline-flex; align-items: center; gap: 8px; font-size: 19px; font-weight: 600; letter-spacing: -0.3px; color: var(--ink); }\n.own-cursor .cu-wordmark svg { width: 18px; height: 18px; color: var(--ink); }\n.own-cursor .cu-menu { display: flex; gap: 26px; margin: 0 auto; font-size: 14px; font-weight: 500; color: var(--body); }\n.own-cursor .cu-menu a:hover { color: var(--ink); }\n.own-cursor .cu-nav-right { display: flex; align-items: center; gap: 14px; margin-left: auto; }\n.own-cursor .cu-nav-link { font-size: 14px; font-weight: 500; color: var(--body); }\n.own-cursor .cu-nav-link:hover { color: var(--ink); }\n.own-cursor .cu-burger { display: none; flex-direction: column; gap: 4px; width: 40px; height: 40px; align-items: center; justify-content: center; border: 1px solid var(--hairline-strong); border-radius: var(--r-md); background: var(--surface-card); }\n.own-cursor .cu-burger span { display: block; width: 18px; height: 2px; background: var(--ink); }\n\n/* ── buttons ──────────────────────────────────────────────────────────────── */\n.own-cursor .cu-btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; height: 40px; padding: 0 18px; border: 1px solid transparent; border-radius: var(--r-md); font-family: var(--font-body); font-size: 14px; font-weight: 500; line-height: 1; transition: background-color .18s, border-color .18s; }\n.own-cursor .cu-btn-lg { height: 44px; padding: 0 20px; }\n.own-cursor .cu-btn-primary { background: var(--primary); color: var(--on-primary); }\n.own-cursor .cu-btn-primary:hover { background: var(--primary-active); }\n.own-cursor .cu-btn-ink { background: var(--ink); color: var(--canvas); }\n.own-cursor .cu-btn-ink:hover { background: #000; }\n.own-cursor .cu-btn-secondary { background: var(--surface-card); color: var(--ink); border-color: var(--hairline-strong); }\n.own-cursor .cu-btn-secondary:hover { border-color: var(--ink); }\n.own-cursor .cu-link { display: inline-flex; align-items: center; gap: 8px; font-size: 15px; color: var(--ink); }\n.own-cursor .cu-link:hover { text-decoration: underline; text-underline-offset: 3px; }\n\n.own-cursor .cu-eyebrow { display: inline-block; margin-bottom: 14px; font-size: 11px; font-weight: 600; letter-spacing: .88px; text-transform: uppercase; color: var(--muted); }\n.own-cursor .cu-h2 { font-family: var(--font-display); font-size: clamp(30px, 4.2cqi, 44px); font-weight: 400; line-height: 1.15; letter-spacing: -0.9px; }\n.own-cursor .cu-lead { margin-top: 14px; max-width: 52ch; font-size: 16px; line-height: 1.5; color: var(--body); }\n\n/* ── hero ──────────────────────────────────────────────────────────────────── */\n.own-cursor .cu-hero { padding: var(--section) var(--gut) clamp(40px, 6cqi, 72px); text-align: center; }\n.own-cursor .cu-hero-title { font-family: var(--font-display); font-size: clamp(40px, 7cqi, 72px); font-weight: 400; line-height: 1.1; letter-spacing: -2.16px; max-width: 18ch; margin: 0 auto; }\n.own-cursor .cu-hero-sub { margin: 20px auto 0; max-width: 58ch; font-size: 17px; line-height: 1.5; color: var(--body); }\n.own-cursor .cu-hero-cta { display: flex; align-items: center; justify-content: center; gap: 22px; flex-wrap: wrap; margin-top: 28px; }\n\n/* ── IDE mockup (the only \"elevated\" element) ──────────────────────────────── */\n.own-cursor .cu-ide { margin: clamp(36px, 5cqi, 64px) auto 0; width: min(1000px, 100%); border: 1px solid var(--hairline); border-radius: var(--r-lg); background: var(--surface-card); overflow: hidden; text-align: left; }\n.own-cursor .cu-ide-bar { display: flex; align-items: center; gap: 4px; padding: 8px 10px; border-bottom: 1px solid var(--hairline); background: var(--canvas-soft); }\n.own-cursor .cu-ide-tab { padding: 6px 12px; border-radius: var(--r-sm); font-family: var(--font-mono); font-size: 12px; color: var(--muted); }\n.own-cursor .cu-ide-tab-on { background: var(--surface-card); color: var(--ink); border: 1px solid var(--hairline); }\n.own-cursor .cu-ide-spacer { flex: 1; }\n.own-cursor .cu-ide-chip { padding: 4px 10px; border-radius: var(--r-pill); background: var(--surface-strong); font-size: 11px; font-weight: 600; letter-spacing: .4px; color: var(--ink); }\n.own-cursor .cu-ide-body { display: grid; grid-template-columns: 168px 1.5fr 1fr; min-height: 300px; }\n.own-cursor .cu-ide-side { display: grid; gap: 4px; align-content: start; padding: 16px 12px; border-right: 1px solid var(--hairline); background: var(--canvas-soft); }\n.own-cursor .cu-ide-h { font-family: var(--font-mono); font-size: 11px; letter-spacing: .4px; text-transform: uppercase; color: var(--muted); margin-bottom: 8px; }\n.own-cursor .cu-ide-file { padding: 6px 8px; border-radius: var(--r-sm); font-family: var(--font-mono); font-size: 12px; color: var(--body); }\n.own-cursor .cu-ide-file-on { background: var(--surface-card); color: var(--ink); border: 1px solid var(--hairline); }\n.own-cursor .cu-ide-main { padding: 18px; }\n.own-cursor .cu-ide-pre { margin: 0; font-family: var(--font-mono); font-size: 13px; line-height: 1.65; color: var(--ink); }\n.own-cursor .cu-ide-pre code { font: inherit; }\n.own-cursor .cu-ln { display: inline-block; width: 20px; color: var(--muted-soft); user-select: none; }\n.own-cursor .cu-k { color: #a23b00; }\n.own-cursor .cu-s { color: #1f6f4a; }\n.own-cursor .cu-n { color: #7a4ea0; }\n.own-cursor .cu-fn { color: #1a4ea0; }\n.own-cursor .cu-c { color: var(--muted); }\n.own-cursor .cu-ide-chat { display: grid; gap: 10px; align-content: start; padding: 16px; border-left: 1px solid var(--hairline); background: var(--canvas-soft); }\n.own-cursor .cu-ide-msg { padding: 10px 12px; border-radius: var(--r-md); font-size: 13px; line-height: 1.5; }\n.own-cursor .cu-ide-msg-user { background: var(--surface-card); border: 1px solid var(--hairline); color: var(--body); }\n.own-cursor .cu-ide-msg-ai { background: var(--surface-strong); color: var(--ink); }\n\n/* ── AI timeline ───────────────────────────────────────────────────────────── */\n.own-cursor .cu-timeline { padding: var(--section) var(--gut); background: var(--canvas-soft); }\n.own-cursor .cu-timeline-head { text-align: center; max-width: 640px; margin: 0 auto clamp(32px, 5cqi, 48px); }\n.own-cursor .cu-steps { list-style: none; display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px; max-width: 1080px; margin: 0 auto; }\n.own-cursor .cu-step { display: grid; gap: 12px; align-content: start; padding: 20px; border: 1px solid var(--hairline); border-radius: var(--r-lg); background: var(--surface-card); }\n.own-cursor .cu-step-pill { justify-self: start; padding: 4px 10px; border-radius: var(--r-pill); font-size: 11px; font-weight: 600; letter-spacing: .88px; text-transform: uppercase; color: var(--ink); }\n.own-cursor .cu-step-think { background: var(--timeline-thinking); }\n.own-cursor .cu-step-grep { background: var(--timeline-grep); }\n.own-cursor .cu-step-read { background: var(--timeline-read); }\n.own-cursor .cu-step-edit { background: var(--timeline-edit); }\n.own-cursor .cu-step-done { background: var(--timeline-done); color: var(--on-primary); }\n.own-cursor .cu-step p { font-size: 14px; line-height: 1.5; color: var(--body); }\n.own-cursor .cu-step time { font-family: var(--font-mono); font-size: 12px; color: var(--muted); }\n.own-cursor .cu-step-bar { height: 4px; border-radius: var(--r-pill); background: var(--surface-strong); overflow: hidden; }\n.own-cursor .cu-step-bar span { display: block; height: 100%; border-radius: var(--r-pill); background: var(--ink); }\n\n/* ── features ──────────────────────────────────────────────────────────────── */\n.own-cursor .cu-features { padding: var(--section) var(--gut); }\n.own-cursor .cu-features-head { text-align: center; max-width: 640px; margin: 0 auto clamp(32px, 5cqi, 48px); }\n.own-cursor .cu-feature-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }\n.own-cursor .cu-feature { display: grid; gap: 10px; align-content: start; padding: 24px; border: 1px solid var(--hairline); border-radius: var(--r-lg); background: var(--surface-card); }\n.own-cursor .cu-feature-ico { display: grid; place-items: center; width: 40px; height: 40px; border-radius: var(--r-md); background: var(--canvas-soft); border: 1px solid var(--hairline); color: var(--ink); }\n.own-cursor .cu-feature-ico svg { width: 20px; height: 20px; }\n.own-cursor .cu-feature h3 { font-size: 18px; font-weight: 600; line-height: 1.4; }\n.own-cursor .cu-feature p { font-size: 15px; line-height: 1.5; color: var(--body); }\n\n/* ── comparison ────────────────────────────────────────────────────────────── */\n.own-cursor .cu-compare { padding: 0 var(--gut) var(--section); }\n.own-cursor .cu-compare-card { display: grid; grid-template-columns: 1fr 1fr; border: 1px solid var(--hairline); border-radius: var(--r-lg); background: var(--surface-card); overflow: hidden; }\n.own-cursor .cu-compare-col { padding: 32px; }\n.own-cursor .cu-compare-col h3 { font-size: 20px; font-weight: 600; margin-bottom: 16px; }\n.own-cursor .cu-compare-col ul { list-style: none; display: grid; gap: 12px; }\n.own-cursor .cu-compare-col li { position: relative; padding-left: 24px; font-size: 15px; color: var(--body); }\n.own-cursor .cu-compare-col li::before { content: ''; position: absolute; left: 0; top: 7px; width: 11px; height: 6px; border-left: 2px solid var(--semantic-success); border-bottom: 2px solid var(--semantic-success); transform: rotate(-45deg); }\n.own-cursor .cu-compare-other { border-left: 1px solid var(--hairline); background: var(--canvas-soft); }\n.own-cursor .cu-compare-other h3 { color: var(--muted); }\n.own-cursor .cu-compare-other li::before { border-color: var(--semantic-error); width: 12px; height: 0; border-left: 0; border-bottom: 2px solid var(--semantic-error); transform: none; top: 11px; }\n\n/* ── code section ──────────────────────────────────────────────────────────── */\n.own-cursor .cu-code-sec { display: grid; grid-template-columns: 1fr 1.15fr; gap: clamp(28px, 4cqi, 56px); align-items: center; padding: var(--section) var(--gut); }\n.own-cursor .cu-code-block { border: 1px solid var(--hairline); border-radius: var(--r-lg); background: var(--surface-card); overflow: hidden; }\n.own-cursor .cu-code-bar { display: flex; align-items: center; justify-content: space-between; padding: 12px 18px; border-bottom: 1px solid var(--hairline); background: var(--canvas-soft); font-family: var(--font-mono); font-size: 12px; color: var(--muted); }\n.own-cursor .cu-copy { border: 1px solid var(--hairline-strong); border-radius: var(--r-sm); background: var(--surface-card); color: var(--body); font-family: var(--font-mono); font-size: 11px; padding: 4px 10px; }\n.own-cursor .cu-copy:hover { color: var(--ink); border-color: var(--ink); }\n.own-cursor .cu-pre { margin: 0; padding: 20px; overflow-x: auto; font-family: var(--font-mono); font-size: 13px; line-height: 1.65; color: var(--ink); }\n.own-cursor .cu-pre code { font: inherit; }\n\n/* ── pricing ────────────────────────────────────────────────────────────────── */\n.own-cursor .cu-pricing { padding: var(--section) var(--gut); background: var(--canvas-soft); }\n.own-cursor .cu-pricing-head { text-align: center; max-width: 640px; margin: 0 auto clamp(32px, 5cqi, 48px); }\n.own-cursor .cu-tier-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; align-items: stretch; }\n.own-cursor .cu-tier { display: grid; gap: 12px; align-content: start; padding: 32px; border: 1px solid var(--hairline); border-radius: var(--r-lg); background: var(--surface-card); }\n.own-cursor .cu-tier-name { font-size: 13px; font-weight: 600; letter-spacing: .04em; text-transform: uppercase; color: var(--muted); }\n.own-cursor .cu-tier-price { font-family: var(--font-display); font-size: clamp(30px, 3.4cqi, 44px); font-weight: 400; line-height: 1.05; letter-spacing: -0.9px; }\n.own-cursor .cu-tier-price span { font-family: var(--font-body); font-size: 13px; color: var(--muted); letter-spacing: 0; }\n.own-cursor .cu-tier ul { list-style: none; display: grid; gap: 10px; margin: 8px 0 12px; padding-top: 18px; border-top: 1px solid var(--hairline); font-size: 15px; color: var(--body); }\n.own-cursor .cu-tier .cu-btn { width: 100%; }\n.own-cursor .cu-tier-featured { background: var(--ink); border-color: var(--ink); color: var(--canvas); }\n.own-cursor .cu-tier-featured .cu-tier-name { color: rgba(255, 255, 255, .6); }\n.own-cursor .cu-tier-featured .cu-tier-price { color: var(--canvas); }\n.own-cursor .cu-tier-featured ul { border-top-color: rgba(255, 255, 255, .16); color: rgba(255, 255, 255, .78); }\n\n/* ── CTA band ──────────────────────────────────────────────────────────────── */\n.own-cursor .cu-cta { padding: clamp(56px, 8cqi, 96px) var(--gut); text-align: center; }\n.own-cursor .cu-cta-title { font-family: var(--font-display); font-size: clamp(30px, 4.2cqi, 44px); font-weight: 400; line-height: 1.2; letter-spacing: -0.9px; margin-bottom: 24px; }\n\n/* ── footer ─────────────────────────────────────────────────────────────────── */\n.own-cursor .cu-foot { padding: clamp(48px, 6cqi, 64px) var(--gut) 32px; border-top: 1px solid var(--hairline); }\n.own-cursor .cu-foot-cols { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; padding-bottom: 40px; }\n.own-cursor .cu-foot-col { display: grid; gap: 10px; align-content: start; }\n.own-cursor .cu-foot-col h3 { font-size: 13px; font-weight: 600; color: var(--ink); margin-bottom: 4px; }\n.own-cursor .cu-foot-col a { font-size: 14px; color: var(--body); }\n.own-cursor .cu-foot-col a:hover { color: var(--ink); }\n.own-cursor .cu-legal { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; padding-top: 22px; border-top: 1px solid var(--hairline); font-size: 13px; color: var(--muted); }\n\n/* ── responsive ───────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-cursor .cu-menu { display: none; }\n  .own-cursor .cu-burger { display: flex; }\n  .own-cursor .cu-ide-body { grid-template-columns: 150px 1.4fr 1fr; }\n  .own-cursor .cu-steps { grid-template-columns: repeat(2, 1fr); }\n  .own-cursor .cu-feature-grid { grid-template-columns: 1fr; }\n  .own-cursor .cu-code-sec { grid-template-columns: 1fr; }\n  .own-cursor .cu-tier-grid { grid-template-columns: 1fr; }\n}\n@container frame (max-width: 760px) {\n  .own-cursor .cu-nav { top: 66px; height: 58px; gap: 10px; }\n  .own-cursor .cu-ide-body { grid-template-columns: 1fr; }\n  .own-cursor .cu-ide-side { border-right: 0; border-bottom: 1px solid var(--hairline); }\n  .own-cursor .cu-ide-chat { border-left: 0; border-top: 1px solid var(--hairline); }\n  .own-cursor .cu-compare-card { grid-template-columns: 1fr; }\n  .own-cursor .cu-compare-other { border-left: 0; border-top: 1px solid var(--hairline); }\n  .own-cursor .cu-foot-cols { grid-template-columns: repeat(2, 1fr); }\n}\n@container frame (max-width: 430px) {\n  .own-cursor .cu-steps { grid-template-columns: 1fr; }\n  .own-cursor .cu-hero-cta { flex-direction: column; align-items: stretch; }\n  .own-cursor .cu-foot-cols { grid-template-columns: 1fr; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-cursor *, .own-cursor *::before, .own-cursor *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — in Cursor's design language, for showcase.html ══════════════
   Registers window.OWN_LAYOUTS['cursor'].init(root). Renders the AI-timeline
   steps (pastel pills) and the feature grid, wires the SQL copy button, and
   returns a cleanup that detaches every listener and clears pending timeouts. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  /* stage, label class, copy, elapsed */
  var STEPS = [
    { cls: 'cu-step-think', label: 'Thinking', text: 'Reading the request and planning the reconciliation.', t: '0.0s', pct: 12 },
    { cls: 'cu-step-grep', label: 'Grepping', text: 'Searching the ops model for week 41 line shifts.', t: '0.3s', pct: 34 },
    { cls: 'cu-step-read', label: 'Reading', text: 'Loading shift rows for all 14 lines.', t: '0.6s', pct: 58 },
    { cls: 'cu-step-edit', label: 'Editing', text: 'Writing the flagged-lines table and digest draft.', t: '1.1s', pct: 84 },
    { cls: 'cu-step-done', label: 'Done', text: 'Reconciled in 1.8s — 3 anomalies flagged.', t: '1.8s', pct: 100 }
  ];
  var FEATURES = [
    { ico: '<path d="M4 7h16M4 12h16M4 17h10" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/>', h: 'Governed ops model', p: 'SQL and the agent read the same definitions. No team-specific drift.' },
    { ico: '<circle cx="12" cy="12" r="8" fill="none" stroke="currentColor" stroke-width="1.8"/><path d="M12 7.5V12l3 2" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/>', h: 'Replayable agent runs', p: 'Every step is named and time-stamped. Rerun it and get the same answer.' },
    { ico: '<path d="M5 12l4.5 4.5L19 7" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>', h: 'Digests that land', p: 'The night shift gets the reconciled board on their own clock.' }
  ];

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  OWN['cursor'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var timeouts = [];
      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }
      function later(fn, ms) { var id = window.setTimeout(fn, ms); timeouts.push(id); return id; }
      function $(s) { return root.querySelector(s); }

      var steps = $('#cuSteps');
      if (steps) {
        steps.innerHTML = STEPS.map(function (s) {
          return '<li class="cu-step">'
            + '<span class="cu-step-pill ' + s.cls + '">' + esc(s.label) + '</span>'
            + '<p>' + esc(s.text) + '</p>'
            + '<div class="cu-step-bar"><span style="width:' + s.pct + '%"></span></div>'
            + '<time>' + esc(s.t) + '</time>'
            + '</li>';
        }).join('');
      }

      var grid = $('#cuFeatureGrid');
      if (grid) {
        grid.innerHTML = FEATURES.map(function (f) {
          return '<article class="cu-feature">'
            + '<span class="cu-feature-ico" aria-hidden="true"><svg viewBox="0 0 24 24">' + f.ico + '</svg></span>'
            + '<h3>' + esc(f.h) + '</h3>'
            + '<p>' + esc(f.p) + '</p>'
            + '</article>';
        }).join('');
      }

      var copy = $('#cuCopy');
      on(copy, 'click', function () {
        var code = $('#cuCode');
        var text = code ? code.textContent : '';
        function done() { if (copy) { copy.textContent = 'Copied'; later(function () { if (copy) copy.textContent = 'Copy'; }, 1400); } }
        try {
          if (navigator.clipboard && navigator.clipboard.writeText) { navigator.clipboard.writeText(text).then(done, done); }
          else { done(); }
        } catch (e) { done(); }
      });

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        timeouts.forEach(function (id) { clearTimeout(id); });
      };
    }
  };
})();
